<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDown, ArrowUp, ArrowUpDown } from '@lucide/vue'
import { useTheme } from '@/shared/theme/theme'
import fixture from './marketBreadth.fixture.json'

const columns = ['New highs (%)','New lows (%)','12W highs (%)','12W lows (%)','4W highs (%)','4W lows (%)','Above 10D MA (%)','Above 50D MA (%)','Above 200D MA (%)','Above BB (%)','Below BB (%)','RSI < 30 (%)','RSI > 70 (%)','A/D','Cumulative A/D','10D A/D ratio','McClellan Osc.','McClellan Sum.','Panic Composite']
const details = ['Share of constituents at new highs (%)','Share of constituents at new lows (%)','Share of constituents at 12-week highs (%)','Share of constituents at 12-week lows (%)','Share of constituents at 4-week highs (%)','Share of constituents at 4-week lows (%)','Share of constituents above their 10-day moving average (%)','Share of constituents above their 50-day moving average (%)','Share of constituents above their 200-day moving average (%)','Share of constituents above the upper Bollinger Band (%)','Share of constituents below the lower Bollinger Band (%)','Share of constituents with RSI below 30 (%)','Share of constituents with RSI above 70 (%)','Advancing minus declining constituents','Cumulative advance–decline line reading','10-day advance–decline ratio','McClellan Oscillator reading','McClellan Summation Index reading','Panic Composite reading']
type Tint = { foreground: string; background: string; label: string }
const lightPalette: Record<string, Tint> = {
  g3: { foreground: '#00875d', background: '#d9f2e7', label: 'Pessimism' }, g2: { foreground: '#32a867', background: '#e4f5e9', label: 'Pessimism' }, g1: { foreground: '#8acf9d', background: '#f1f9f2', label: 'Pessimism' },
  r1: { foreground: '#efb5b2', background: '#fdf0ef', label: 'Optimism' }, r2: { foreground: '#ec7772', background: '#fce0de', label: 'Optimism' }, r3: { foreground: '#c63d45', background: '#f8d2d4', label: 'Optimism' },
}
const darkPalette: Record<string, Tint> = {
  g3: { foreground: '#34d399', background: 'rgba(52,211,153,.18)', label: 'Pessimism' }, g2: { foreground: '#4ade80', background: 'rgba(74,222,128,.12)', label: 'Pessimism' }, g1: { foreground: '#86efac', background: 'rgba(134,239,172,.08)', label: 'Pessimism' },
  r1: { foreground: '#fda4af', background: 'rgba(253,164,175,.08)', label: 'Optimism' }, r2: { foreground: '#fb7185', background: 'rgba(251,113,133,.12)', label: 'Optimism' }, r3: { foreground: '#f43f5e', background: 'rgba(244,63,94,.18)', label: 'Optimism' },
}
const { isDarkTheme } = useTheme()
const palette = computed<Record<string, Tint>>(() => (isDarkTheme.value ? darkPalette : lightPalette))
const rows: { symbol: string; group: string; values: (number | null)[]; colors: Record<string, string> }[] = fixture.map((row) => ({ ...row, colors: Object.fromEntries(Object.entries(row.colors).filter((entry): entry is [string, string] => typeof entry[1] === 'string')) }))
const query = ref('')
const scope = ref<'all' | 'D' | 'F'>('all')
const sort = ref(-1)
const ascending = ref(false)
const metric = ref(8)
const selected = ref(['SPY', 'QQQ', 'IWM'])
const status = ref('Use the checkboxes below to change this comparison.')
const filtered = computed(() => {
  const term = query.value.trim().toLowerCase()
  const result = rows.filter((row) => (scope.value === 'all' || row.group === scope.value) && row.symbol.toLowerCase().includes(term))
  if (sort.value >= 0) result.sort((left, right) => { const a = left.values[sort.value], b = right.values[sort.value]; return a === null ? 1 : b === null ? -1 : (a - b) * (ascending.value ? 1 : -1) })
  return result
})
const comparison = computed(() => selected.value.map((symbol) => rows.find((row) => row.symbol === symbol)).filter((row): row is typeof rows[number] => !!row))
function toggleSort(index: number) { ascending.value = sort.value === index ? !ascending.value : false; sort.value = index }
function toggleSelected(symbol: string, checked: boolean, input?: HTMLInputElement) {
  if (checked && selected.value.length >= 4) { if (input) input.checked = false; status.value = 'Select up to four markets. Remove one to add another.'; return }
  selected.value = checked ? [...selected.value, symbol] : selected.value.filter((item) => item !== symbol)
  status.value = 'Blue bars compare the selected reading on the same scale.'
}
function reset() { query.value = ''; scope.value = 'all'; sort.value = -1; ascending.value = false; metric.value = 8; selected.value = ['SPY', 'QQQ', 'IWM']; status.value = 'Use the checkboxes below to change this comparison.' }
const tint = (row: typeof rows[number], index: number) => palette.value[row.colors[String(index)]]
</script>

<template>
  <section class="space-y-4" data-testid="market-breadth-content">
    <div class="grid gap-4 lg:grid-cols-[1.1fr_1fr]"><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-6 shadow-sm"><p class="text-[10px] font-extrabold uppercase tracking-[.13em] text-[var(--app-primary)]">Index &amp; ETF breadth</p><h2 class="mt-2 text-2xl font-semibold">Market coverage</h2><div class="mt-6 flex flex-wrap gap-8"><div v-for="item in [{count:17,label:'Domestic indexes & ETFs'},{count:16,label:'Foreign indexes'},{count:19,label:'Breadth measures'}]" :key="item.label"><strong class="block text-3xl text-[var(--app-primary)]">{{ item.count }}</strong><span class="text-xs text-[var(--app-text-muted)]">{{ item.label }}</span></div></div></section><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5 shadow-sm"><div class="mb-3 flex items-center justify-between gap-3"><h2 class="font-semibold">Compare indexes &amp; ETFs</h2><span class="rounded bg-[var(--app-primary-soft)] px-2 py-1 text-xs font-semibold text-[var(--app-primary)]">{{ selected.length }} / 4 selected</span></div><select v-model.number="metric" class="mb-3 w-full rounded-md border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2 text-xs" aria-label="Breadth measure to compare"><option v-for="(column,index) in columns.slice(0,13)" :key="column" :value="index">{{ column }}</option></select><div v-if="comparison.length" class="space-y-3"><div v-for="row in comparison" :key="row.symbol" class="grid grid-cols-[42px_minmax(0,1fr)_60px_20px] items-center gap-2 text-xs"><b>{{ row.symbol }}</b><div class="h-[7px] overflow-hidden rounded-full bg-[var(--app-primary-soft)]"><div class="h-full rounded-full bg-[var(--app-primary)]" :style="{ width: `${Math.max(0, Math.min(100, row.values[metric] ?? 0))}%` }" /></div><strong class="text-right text-sm text-[var(--app-primary)]">{{ row.values[metric] ?? '—' }}<small v-if="row.values[metric] !== null">%</small></strong><button type="button" :aria-label="`Remove ${row.symbol} from comparison`" class="text-lg text-[var(--app-text-muted)]" @click="toggleSelected(row.symbol, false)">×</button></div></div><p v-else class="py-3 text-xs text-[var(--app-text-muted)]">Select up to four indexes or ETFs to compare the same breadth measure.</p><div class="ml-[50px] mr-[80px] mt-2 flex justify-between text-[10px] text-[var(--app-text-muted)]"><span>0%</span><span>100%</span></div><p role="status" class="mt-2 min-h-4 text-[11px] text-[var(--app-primary)]">{{ status }}</p></section></div>
    <section class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">Market breadth explorer</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">All 19 measures are shown. Scroll horizontally to see more columns; select a heading to sort.</p></div><span class="rounded bg-[var(--app-primary-soft)] px-2 py-1 text-xs font-semibold text-[var(--app-primary)]">{{ filtered.length }} of 33 markets</span></header><div class="flex flex-wrap items-center gap-2 p-4"><input v-model="query" type="search" placeholder="Search an index or ETF…" aria-label="Search indexes and ETFs" class="min-w-[210px] flex-1 rounded-md border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2 text-xs" /><select v-model="scope" aria-label="Market group" class="rounded-md border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2 text-xs"><option value="all">All markets · 33</option><option value="D">Domestic · 17</option><option value="F">Foreign · 16</option></select><button type="button" class="rounded-md border border-[var(--app-border)] bg-[var(--app-primary-soft)] px-3 py-2 text-xs font-semibold text-[var(--app-primary)]" @click="reset">Reset</button></div><div class="flex flex-wrap items-center justify-between gap-3 border-y border-[var(--app-border)] bg-[var(--app-surface-soft)] px-4 py-3 text-[10px] text-[var(--app-text-muted)]"><span>Color shows sentiment relative to each measure’s recent range.</span><div class="flex items-center gap-2"><span>Pessimism</span><div class="flex gap-0.5"><i v-for="key in ['g3','g2','g1']" :key="key" class="h-[11px] w-[14px] rounded-[2px]" :style="{ background: palette[key].foreground }" /><i class="h-[11px] w-[14px] rounded-[2px] border border-[var(--app-border)] bg-[var(--app-surface)]" /><i v-for="key in ['r1','r2','r3']" :key="key" class="h-[11px] w-[14px] rounded-[2px]" :style="{ background: palette[key].foreground }" /></div><span>Optimism</span></div></div>
      <div class="max-h-[650px] overflow-auto" role="region" aria-label="Market breadth table, 19 measures; scroll horizontally for all columns" tabindex="0"><table class="w-full min-w-[1550px] border-collapse text-right text-xs tabular-nums"><thead class="sticky top-0 z-20 bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr><th class="sticky left-0 z-30 w-9 border-b border-[var(--app-border)] bg-[var(--app-surface-muted)] p-2"><span class="sr-only">Compare</span></th><th class="sticky left-9 z-30 w-[100px] border-b border-[var(--app-border)] bg-[var(--app-surface-muted)] p-2 text-left">Index / ETF</th><th v-for="(column,index) in columns" :key="column" class="min-w-[76px] border-b border-[var(--app-border)] px-1.5 py-2"><button type="button" :title="details[index]" class="inline-flex items-center gap-1 text-right font-semibold" @click="toggleSort(index)">{{ column }}<ArrowUp v-if="sort === index && ascending" :size="12"/><ArrowDown v-else-if="sort === index" :size="12"/><ArrowUpDown v-else :size="12"/></button></th></tr></thead><tbody><template v-for="(row,index) in filtered" :key="row.symbol"><tr v-if="sort < 0 && (index === 0 || filtered[index - 1].group !== row.group)" class="bg-[var(--app-primary-soft)] text-left text-[11px] font-bold text-[var(--app-text-secondary)]"><td :colspan="21" class="sticky left-0 px-4 py-2">{{ row.group === 'D' ? 'Domestic Index and ETF Breadth' : 'Foreign Index Breadth' }} <span class="ml-1 rounded bg-[var(--app-surface)] px-1.5 py-0.5 text-[10px]">{{ filtered.filter((item) => item.group === row.group).length }}</span></td></tr><tr class="border-b border-[var(--app-border-muted)] hover:bg-[var(--app-surface-hover)]"><td class="sticky left-0 z-10 bg-[var(--app-surface)] p-2 text-left"><input type="checkbox" :checked="selected.includes(row.symbol)" :aria-label="`Compare ${row.symbol}`" class="accent-[var(--app-primary)]" @change="toggleSelected(row.symbol, ($event.target as HTMLInputElement).checked, $event.target as HTMLInputElement)" /></td><th scope="row" class="sticky left-9 z-10 bg-[var(--app-surface)] p-2 text-left font-semibold text-[var(--app-primary)]">{{ row.symbol }}</th><td v-for="(value,column) in row.values" :key="column" class="relative px-1.5 py-2" :style="tint(row, column) ? { background: tint(row, column).background, boxShadow: `inset 3px 0 ${tint(row, column).foreground}` } : undefined" :title="tint(row, column) ? `${tint(row, column).label} relative to this measure’s recent range` : value === null ? 'No reading available' : details[column]">{{ value === null ? '—' : value }}</td></tr></template><tr v-if="!filtered.length"><td colspan="21" class="p-8 text-center text-[var(--app-text-muted)]">No indexes or ETFs match your search.</td></tr></tbody></table></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs leading-5 text-[var(--app-text-muted)]">Percentage columns show the share of constituents. MA = moving average; BB = Bollinger Bands; A/D = advances minus declines. “—” means no available reading.</footer></section>
  </section>
</template>
